        self.names = [str(n) for n in self.t['names']]
        h, sp = self.t['hist_row'], self.t['split']
        self.lf_train = np.flatnonzero((h<0)&(sp==0)&self.m.any(1))
        self.gs_train = np.flatnonzero((h>=0)&(sp==0))
        self.gs_test = np.flatnonzero((h>=0)&(sp==2))
